-- Reconciled file exports for QuickBooks Enterprise 2021 Desktop.
create table public.quickbooks_export_batches(export_batch_id uuid primary key default gen_random_uuid(),export_kind text not null check(export_kind in('MASTER_LISTS','ESTIMATES','INVOICES','PURCHASE_ORDERS')),filename text not null,record_ids jsonb not null default'[]',record_count int not null check(record_count>=0),status text not null default'EXPORTED'check(status in('EXPORTED','IMPORTED','FAILED')),exported_at timestamptz not null default now(),imported_at timestamptz,quickbooks_reference text,notes text,created_at timestamptz not null default now(),created_by text not null default'system',updated_at timestamptz not null default now(),updated_by text);
alter table public.quickbooks_export_batches enable row level security;create policy factory_read_qb_exports on public.quickbooks_export_batches for select using(has_factory_role(auth.uid(),array['admin','accounts','viewer']));
create or replace function public.record_quickbooks_export(p_kind text,p_record_ids jsonb,p_filename text)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;begin if not has_factory_role(auth.uid(),array['admin','accounts'])then raise exception'not authorized';end if;if p_kind not in('MASTER_LISTS','ESTIMATES','INVOICES','PURCHASE_ORDERS')then raise exception'invalid export kind';end if;if jsonb_typeof(p_record_ids)<>'array'then raise exception'record ids must be an array';end if;insert into quickbooks_export_batches(export_kind,filename,record_ids,record_count,created_by)values(p_kind,p_filename,p_record_ids,jsonb_array_length(p_record_ids),auth.uid()::text)returning export_batch_id into v_id;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'QuickBooks Export Created','quickbooks_export_batches',v_id,jsonb_build_object('kind',p_kind,'filename',p_filename,'record_count',jsonb_array_length(p_record_ids)));return v_id;end$$;
create or replace function public.confirm_quickbooks_import(p_batch uuid,p_reference text,p_notes text default null)returns uuid language plpgsql security definer set search_path=public as $$begin if not has_factory_role(auth.uid(),array['admin','accounts'])then raise exception'not authorized';end if;if nullif(trim(p_reference),'')is null then raise exception'QuickBooks reference is required';end if;update quickbooks_export_batches set status='IMPORTED',imported_at=now(),quickbooks_reference=trim(p_reference),notes=nullif(trim(p_notes),''),updated_at=now(),updated_by=auth.uid()::text where export_batch_id=p_batch and status='EXPORTED';if not found then raise exception'open export batch not found';end if;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'QuickBooks Import Confirmed','quickbooks_export_batches',p_batch,jsonb_build_object('quickbooks_reference',trim(p_reference)));return p_batch;end$$;
revoke all on function public.record_quickbooks_export(text,jsonb,text)from public;revoke all on function public.confirm_quickbooks_import(uuid,text,text)from public;grant execute on function public.record_quickbooks_export(text,jsonb,text)to authenticated;grant execute on function public.confirm_quickbooks_import(uuid,text,text)to authenticated;
